function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 1 || grid.length > 100) return 'grid needs 1 to 100 rows.';
  const n = grid[0].length;
  if (n < 1 || n > 100) return 'grid needs 1 to 100 columns.';
  if (grid.some(row => row.length !== n)) return 'Every row must have the same length.';
  if (grid.some(row => row.some(v => !Number.isInteger(v) || v < 0 || v > 1000000000))) return 'Each value is an integer between 0 and 10^9.';
  return null;
}

