function maximumMinimumPath(grid) {
  const rows = grid.length;
  const cols = grid[0].length;
  const best = Array.from({ length: rows }, () => new Array(cols).fill(-1));
  const directions = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const heap = [];

  const push = (item) => {
    heap.push(item);
    let child = heap.length - 1;
    while (child > 0) {
      const parent = (child - 1) >> 1;
      if (heap[parent][0] >= heap[child][0]) break;
      [heap[parent], heap[child]] = [heap[child], heap[parent]];
      child = parent;
    }
  };
  const pop = () => {
    const top = heap[0];
    const last = heap.pop();
    if (heap.length === 0) return top;
    heap[0] = last;
    let parent = 0;
    while (true) {
      const left = 2 * parent + 1;
      const right = left + 1;
      let largest = parent;
      if (left < heap.length && heap[left][0] > heap[largest][0]) largest = left;
      if (right < heap.length && heap[right][0] > heap[largest][0]) largest = right;
      if (largest === parent) break;
      [heap[parent], heap[largest]] = [heap[largest], heap[parent]];
      parent = largest;
    }
    return top;
  };

  best[0][0] = grid[0][0];
  push([grid[0][0], 0, 0]);
  while (heap.length > 0) {
    const [score, row, col] = pop();
    if (row === rows - 1 && col === cols - 1) return score;
    if (score < best[row][col]) continue;
    for (const [dr, dc] of directions) {
      const nextRow = row + dr;
      const nextCol = col + dc;
      if (nextRow < 0 || nextRow >= rows || nextCol < 0 || nextCol >= cols) continue;
      const nextScore = Math.min(score, grid[nextRow][nextCol]);
      if (nextScore > best[nextRow][nextCol]) {
        best[nextRow][nextCol] = nextScore;
        push([nextScore, nextRow, nextCol]);
      }
    }
  }
  return -1;
}

