function maximumMinimumPath(grid) {
  const m = grid.length, n = grid[0].length;
  // Try every threshold from the largest value down; the first one that still connects the corners wins.
  const values = [...new Set(grid.flat())].sort((a, b) => b - a);
  for (const limit of values) {
    if (grid[0][0] < limit || grid[m - 1][n - 1] < limit) continue;
    const seen = grid.map(r => r.map(() => false));
    const stack = [[0, 0]];
    seen[0][0] = true;
    while (stack.length) {
      const [r, c] = stack.pop();
      for (const [nr, nc] of [[r + 1, c], [r - 1, c], [r, c + 1], [r, c - 1]]) {
        if (nr >= 0 && nr < m && nc >= 0 && nc < n && !seen[nr][nc] && grid[nr][nc] >= limit) {
          seen[nr][nc] = true;
          stack.push([nr, nc]);
        }
      }
    }
    if (seen[m - 1][n - 1]) return limit;
  }
  return -1;
}

