function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const m = int(1, 4), n = int(1, 4), top = [1, 3, 9, 1000000000][int(0, 3)];
    return [Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, top)))];
  }
  const m = int(60, 100), n = int(60, 100);
  const shape = int(0, 2);
  if (shape === 0) return [Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, 1000000000)))];
  if (shape === 1) return [Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, 50)))];
  // Low background with a winding high corridor, so the best path must snake through the grid.
  const grid = Array.from({ length: m }, () => Array.from({ length: n }, () => int(0, 1000)));
  for (let r = 0; r < m; r++) {
    if (r % 2 === 1) grid[r][r % 4 === 1 ? n - 1 : 0] = int(500000, 1000000000);
    else for (let c = 0; c < n; c++) grid[r][c] = int(500000, 1000000000);
  }
  grid[m - 1][n - 1] = int(500000, 1000000000);
  return [grid];
}
